import {
  Mesh,
  PlaneGeometry,
  Object3D,
  Vector3,
  Euler,
  Color,
  Texture,
  RepeatWrapping
} from 'three/webgpu';
import {
  mix,
  exp2,
  mul,
  add,
  sub,
  length,
  pow,
  clamp,
  smoothstep,
  vec2,
  vec3,
  vec4,
  positionLocal,
  normalLocal,
  normalWorld,
  texture,
  uv,
  viewDirection,
  lightingModelStandard,
  float,
  transformDirection,
  objectWorldPosition,
  attribute,
  varying,
  NodeMaterial
} from 'three/tsl';
import { gsap } from 'gsap';
import primitives from '@/primitives';
import { createSDFTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const root = new Object3D();

  // ---------- Plane Background ----------
  const planeGeometry = new PlaneGeometry(6.8, 2.0);
  const gradientTex = ctx.textureLoader.load('data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAn0B9r4ZJOUAAAAASUVORK5CYII=');
  gradientTex.wrapS = RepeatWrapping;
  gradientTex.wrapT = RepeatWrapping;

  const materialNode = lightingModelStandard({
    // albedo: vertical ramp from #121218 to #0b0b10
    albedo: mix(
      new Color('#121218'),
      new Color('#0b0b10'),
      uv().y
    ),
    roughness: float(0.6),
    metalness: float(0.2)
  });

  const planeMaterial = new NodeMaterial();
  planeMaterial.fragmentNode = materialNode;
  planeMaterial.transparent = true;
  planeMaterial.depthWrite = true;

  const planeMesh = new Mesh(planeGeometry, planeMaterial);
  planeMesh.position.set(0, 0, 0);
  root.add(planeMesh);

  // ---------- Hairline Rules ----------
  const hairlineMaterial = new NodeMaterial();
  hairlineMaterial.fragmentNode = add(
    mix(new Color('#23232b'), new Color('#23232b'), float(1.0)),
    vec3(0.0) // just a solid color
  );
  hairlineMaterial.transparent = true;

  // Top hairline
  const topRuleGeom = new PlaneGeometry(6.8, 0.006);
  const topRule = new Mesh(topRuleGeom, hairlineMaterial);
  topRule.position.set(0, 1.0 - 0.003, 0.001);
  root.add(topRule);

  // Bottom hairline (above legal line)
  const bottomRuleGeom = new PlaneGeometry(6.8, 0.006);
  const bottomRule = new Mesh(bottomRuleGeom, hairlineMaterial);
  bottomRule.position.set(0, -1.0 + 0.003 + 0.375 + 0.003, 0.001);
  root.add(bottomRule);

  // ---------- Accent Bar ----------
  const accentMaterial = new NodeMaterial();
  accentMaterial.fragmentNode = new Color('#ff2a38');
  accentMaterial.emissive = vec3(1.4);
  const accentGeom = new PlaneGeometry(0.3, 0.02);
  const accentBar = new Mesh(accentGeom, accentMaterial);
  accentBar.position.set(-2.9, 0.8, 0.001);
  root.add(accentBar);

  // ---------- Text Elements ----------
  const textSpecs = [
    // Wordmark
    {
      text: 'NOVA ATELIER',
      fontSize: 34,
      fontWeight: 600,
      family: 'Lora',
      position: new Vector3(-2.5, 0.6, 0.002)
    },
    // Column 1 Header
    {
      text: 'ATELIER',
      fontSize: 9,
      fontWeight: 700,
      family: 'JetBrains Mono',
      position: new Vector3(-1.6, 0.3, 0.002)
    },
    // Column 1 Links
    {
      text: 'Features',
      fontSize: 13,
      fontWeight: 400,
      family: 'JetBrains Mono',
      position: new Vector3(-1.6, 0.12, 0.002)
    },
    {
      text: 'Collection',
      fontSize: 13,
      fontWeight: 400,
      family: 'JetBrains Mono',
      position: new Vector3(-1.6, -0.06, 0.002)
    },
    {
      text: 'Pricing',
      fontSize: 13,
      fontWeight: 400,
      family: 'JetBrains Mono',
      position: new Vector3(-1.6, -0.24, 0.002)
    },
    // Column 2 Header
    {
      text: 'COMPANY',
      fontSize: 9,
      fontWeight: 700,
      family: 'JetBrains Mono',
      position: new Vector3(-0.3, 0.3, 0.002)
    },
    // Column 2 Links
    {
      text: 'Journal',
      fontSize: 13,
      fontWeight: 400,
      family: 'JetBrains Mono',
      position: new Vector3(-0.3, 0.12, 0.002)
    },
    {
      text: 'Visit the Atelier',
      fontSize: 13,
      fontWeight: 400,
      family: 'JetBrains Mono',
      position: new Vector3(-0.3, -0.06, 0.002)
    },
    {
      text: 'Contact',
      fontSize: 13,
      fontWeight: 400,
      family: 'JetBrains Mono',
      position: new Vector3(-0.3, -0.24, 0.002)
    },
    // Column 3 Header
    {
      text: 'LEGAL',
      fontSize: 9,
      fontWeight: 700,
      family: 'JetBrains Mono',
      position: new Vector3(1.0, 0.3, 0.002)
    },
    // Column 3 Links
    {
      text: 'Privacy',
      fontSize: 13,
      fontWeight: 400,
      family: 'JetBrains Mono',
      position: new Vector3(1.0, 0.12, 0.002)
    },
    {
      text: 'Terms',
      fontSize: 13,
      fontWeight: 400,
      family: 'JetBrains Mono',
      position: new Vector3(1.0, -0.06, 0.002)
    },
    {
      text: 'Warranty',
      fontSize: 13,
      fontWeight: 400,
      family: 'JetBrains Mono',
      position: new Vector3(1.0, -0.24, 0.002)
    },
    // Legal line
    {
      text: '(c) 2026 Nova Atelier. All rights reserved. Machined in Geneva.',
      fontSize: 9,
      fontWeight: 400,
      family: 'JetBrains Mono',
      position: new Vector3(0, -0.9, 0.002)
    }
  ];

  const textMeshes = [];

  for (const spec of textSpecs) {
    const mesh = createSDFTextMesh({
      text: spec.text,
      fontAtlas: ctx.fontAtlas,
      fontSize: spec.fontSize,
      fontWeight: spec.fontWeight,
      family: spec.family,
      color: '#e8ecf2',
      opacity: 1.0
    });
    mesh.position.copy(spec.position);
    root.add(mesh);
    textMeshes.push(mesh);
  }

  // ---------- Hover Interaction ----------
  // (No explicit interactions defined, but we set up a generic hover for links)
  const hoverTimelineMap = new WeakMap();

  textMeshes.forEach(mesh => {
    const isLink = mesh.userData.text && mesh.userData.textStyle === 'link';
    if (!isLink) return;

    mesh.userData.handlers = {
      pointerenter: () => {
        const tl = gsap.timeline();
        tl.to(mesh.material.uniforms.uColor.value, {
          r: 1,
          g: 0.168,
          b: 0.22,
          duration: 0.14,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
        });
        tl.to(mesh.position, {
          z: 0.02,
          duration: 0.14,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
        }, 0);
        hoverTimelineMap.set(mesh, tl);
      },
      pointerleave: () => {
        const tl = hoverTimelineMap.get(mesh);
        if (tl) {
          tl.reverse();
        }
      }
    };
  });

  // ---------- Fade‑up Animation ----------
  const mainTimeline = gsap.timeline();
  mainTimeline.from(root.scale, {
    y: 0.8,
    duration: 0,
    immediateRender: true
  });
  mainTimeline.from(root.position, {
    y: 0.2,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
  }, 0);
  mainTimeline.from(root, {
    opacity: 0,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
  }, 0);

  // ---------- Placement ----------
  root.position.set(
    config.position?.[0] ?? 0,
    config.position?.[1] ?? 0,
    config.position?.[2] ?? 0
  );
  root.rotation.set(
    config.rotation?.[0] ?? 0,
    config.rotation?.[1] ?? 0,
    config.rotation?.[2] ?? 0
  );
  root.scale.set(
    config.scale?.[0] ?? 1,
    config.scale?.[1] ?? 1,
    config.scale?.[2] ?? 1
  );

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    // dispose geometries and materials
    planeGeometry.dispose();
    planeMaterial.dispose();

    topRuleGeom.dispose();
    bottomRuleGeom.dispose();
    accentGeom.dispose();

    hairlineMaterial.dispose();
    accentMaterial.dispose();

    textMeshes.forEach(m => {
      if (m.geometry) m.geometry.dispose();
      if (m.material) m.material.dispose();
    });

    // kill timelines
    mainTimeline.kill();
    hoverTimelineMap.forEach(tl => tl.kill());
  };

  // No explicit cerami primitives to apply

  return root;
}
